package com.manishrawat.realestate.servlet;
import com.manishrawat.realestate.dao.*; import com.manishrawat.realestate.model.User; import com.manishrawat.realestate.thread.NotificationWorker; import jakarta.servlet.*; import jakarta.servlet.annotation.WebServlet; import jakarta.servlet.http.*; import java.io.*; import java.math.BigDecimal; import java.sql.Date;
@WebServlet("/agreement") public class AgreementServlet extends HttpServlet{
 protected void doGet(HttpServletRequest q,HttpServletResponse s)throws ServletException,IOException{try{User u=(User)q.getSession(false).getAttribute("user");q.setAttribute("agreements",new AgreementDAO().list(u));if("ADMIN".equals(u.getRole())||"MANAGER".equals(u.getRole()))q.setAttribute("applications",new ApplicationDAO().approvedWithoutAgreement("ADMIN".equals(u.getRole())?-1:u.getId()));q.getRequestDispatcher("/WEB-INF/views/agreements.jsp").forward(q,s);}catch(Exception e){throw new ServletException("Unable to load agreements.",e);}}
 protected void doPost(HttpServletRequest q,HttpServletResponse s)throws IOException{try{User u=(User)q.getSession(false).getAttribute("user");AgreementDAO d=new AgreementDAO();int tenant;if("create".equals(q.getParameter("action"))){if(!"ADMIN".equals(u.getRole())&& !"MANAGER".equals(u.getRole())){s.sendError(403);return;}int owner="ADMIN".equals(u.getRole())?-1:u.getId();tenant=d.create(Integer.parseInt(q.getParameter("applicationId")),Date.valueOf(q.getParameter("startDate")),Date.valueOf(q.getParameter("endDate")),new BigDecimal(q.getParameter("rent")),owner);NotificationWorker.submit(tenant,"A rental agreement has been created for your approved application.");}else{if(!"ADMIN".equals(u.getRole())&& !"MANAGER".equals(u.getRole())){s.sendError(403);return;}tenant=d.updateStatus(Integer.parseInt(q.getParameter("id")),q.getParameter("status"),u);NotificationWorker.submit(tenant,"Your rental agreement status is now "+q.getParameter("status")+".");}s.sendRedirect(q.getContextPath()+"/agreement?saved=1");}catch(IllegalArgumentException e){s.sendRedirect(q.getContextPath()+"/agreement?error=Invalid+agreement+details");}catch(Exception e){throw new IOException("Unable to save agreement.",e);}}
}
